def f(g):
    H,W=len(g),len(g[0])
    rsep=[r for r,row in enumerate(g) if all(x==0 for x in row)]
    csep=[c for c in range(W) if all(row[c]==0 for row in g)]
    def sgn(n,sps):
        res=[];s=0
        for e in sorted(sps)+[n]:
            if e>s: res.append((s,e))
            s=e+1
        return res
    rb_=sgn(H,rsep); cb_=sgn(W,csep)
    out=[row[:] for row in g]
    for bi,(r0,r1) in enumerate(rb_):
        for bj,(c0,c1) in enumerate(cb_):
            digs={g[r][c] for r in range(r0,r1) for c in range(c0,c1) if g[r][c]!=5}
            if len(digs)==1:
                d=digs.pop()
                for r in range(r0,r1):
                    for c in range(c0,c1):
                        out[r][c]=d+5 if g[r][c]!=0 else 0
    return out
